// Down-migrations 0003 then 0002 undo cleanly to the app/db.cjs schema; both re-apply.
import { describe, it, expect } from 'vitest';
import { env } from 'cloudflare:workers';
import downSql from '../migrations-down/0002_locks_and_rc5_rc9_foundation.down.sql?raw';
import down3Sql from '../migrations-down/0003_batch_guards.down.sql?raw';
import { db } from './helpers.mjs';
// Column dump of app/db.cjs connect(':memory:') at main 7cebef2 (node:sqlite), generated by
// scripts/dump-app-schema.cjs.
import appSchema from './fixtures/app-schema-7cebef2.json';

const statements = sql => sql.split('\n').filter(l => !l.trim().startsWith('--')).join('\n').split(';').map(s => s.trim()).filter(Boolean);
const columns = async table => (await db().all(`SELECT name FROM pragma_table_info('${table}')`)).length;
const objects = async () => (await db().all("SELECT type,name FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' AND name NOT LIKE '_cf_%' AND name<>'d1_migrations' ORDER BY type,name")).map(r => r.type + ':' + r.name);

describe('migration rollback', () => {
  it('0003 down, 0002 down -> schema equals 0001; then 0002 and 0003 re-apply', async () => {
    const before = await objects();
    expect(before).toContain('table:batch_guards');
    const d = db();
    await d.batch(statements(down3Sql).map(s => d.stmt(s)));
    expect(await objects()).not.toContain('table:batch_guards');
    await d.batch(statements(downSql).map(s => d.stmt(s)));
    const after = await objects();
    const counts = { blocks: await columns('blocks'), bookings: await columns('bookings'), stripe_connections: await columns('stripe_connections'), webhook_events: await columns('webhook_events') };
    console.log('after 0002 down: objects', before.length, '->', after.length, 'columns', JSON.stringify(counts));
    expect(after.filter(n => /discount|waitlist|pt_subscriptions|rate_limits|bookings_one_live/.test(n))).toEqual([]);
    expect(after.filter(n => n.startsWith('table:'))).toHaveLength(17);
    expect(counts).toEqual({ blocks: 10, bookings: 22, stripe_connections: 5, webhook_events: 2 });
    // Parity: after down, every table/column (name, type, NOT NULL, default, pk) matches app/db.cjs.
    for (const [table, cols] of Object.entries(appSchema)) {
      const d1cols = (await d.all(`SELECT name,type,"notnull",dflt_value,pk FROM pragma_table_info('${table}') ORDER BY cid`)).map(c => ({ ...c }));
      expect(d1cols, table).toEqual(cols);
    }
    expect(Object.keys(appSchema)).toHaveLength(17);
    for (const prefix of ['0002', '0003']) {
      const up = env.TEST_MIGRATIONS.find(m => m.name.startsWith(prefix)).queries;
      await d.batch(up.map(s => d.stmt(s)));
    }
    expect(await objects()).toEqual(before);
  });
});
